def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    barrier = next((r for r, row in enumerate(g) if all(v == 2 for v in row)), None)
    if barrier is None:
        return g

    top_rows = [r for r in range(barrier) if any(g[r][c] != 0 for c in range(w))]
    bottom_rows = [r for r in range(barrier + 1, h) if any(g[r][c] != 0 for c in range(w))]
    if not top_rows or not bottom_rows:
        return g

    top = top_rows[0]
    bottom = bottom_rows[-1]
    top_color = next((v for v in g[top] if v != 0), None)
    bottom_color = next((v for v in g[bottom] if v != 0), None)
    if top_color is None or top_color != bottom_color:
        return g

    cols = [c for c in range(w) if g[top][c] == top_color and g[bottom][c] == top_color]
    for r in range(top + 1, barrier):
        for c in cols:
            if g[r][c] == 0:
                g[r][c] = 4
    return g
